using System;
using System.Collections.Generic;
using ClientDataAPI;
using NUnit.Framework;

namespace ProjectLucid.Editor
{
    // Routing of the original 1.10.1 HLAutoGenerated ClientDataAPI.Dispatcher.
    public sealed class OriginalClientDataDispatcherTests
    {
        private static NetworkBuffer Empty() => new NetworkBuffer(new byte[0], 0, 0);

        [Test]
        public void PacketsReachTheirHandlerOrFallBackToUnhandled()
        {
            var dispatcher = new Dispatcher();
            var trace = new List<string>();
            dispatcher.OnUnhandledPacket += (int type, ref NetworkBuffer buffer) => trace.Add("unhandled:" + type);
            NetworkBuffer buffer = Empty();
            dispatcher.Dispatch(LocalisedString.ID, ref buffer);
            dispatcher.Dispatch(12345, ref buffer);
            dispatcher.OnUnknownPacket += (int type, ref NetworkBuffer b) => trace.Add("unknown:" + type);
            dispatcher.Dispatch(12345, ref buffer);
            dispatcher.OnLocalisedString += message => trace.Add("localised:" + (message != null));
            dispatcher.Dispatch(LocalisedString.ID, ref buffer);
            Assert.That(trace, Is.EqualTo(new[]
            {
                "unhandled:" + LocalisedString.ID, "unhandled:12345", "unknown:12345", "localised:True"
            }));
        }

        [Test]
        public void HandlerExceptionsGoToTheDispatchErrorHandler()
        {
            var dispatcher = new Dispatcher();
            var failure = new InvalidOperationException("handler failure");
            Exception reported = null;
            int reportedType = 0;
            dispatcher.OnStringTable += message => throw failure;
            dispatcher.OnDispatchError += (Exception ex, int type, ref NetworkBuffer buffer) => { reported = ex; reportedType = type; };
            NetworkBuffer empty = Empty();
            dispatcher.Dispatch(StringTable.ID, ref empty);
            Assert.That(reported, Is.SameAs(failure));
            Assert.That(reportedType, Is.EqualTo(StringTable.ID));
            Assert.DoesNotThrow(() => { var d = new Dispatcher(); d.OnStringTable += _ => throw failure; NetworkBuffer b = Empty(); d.Dispatch(StringTable.ID, ref b); },
                "without an error handler the exception is swallowed");
        }

        [Test]
        public void TriggersReportWhetherAHandlerRan()
        {
            var dispatcher = new Dispatcher();
            Assert.That(dispatcher.TriggerOnSupportedLanguage(new SupportedLanguage()), Is.False);
            SupportedLanguage seen = null;
            dispatcher.OnSupportedLanguage += message => seen = message;
            var language = new SupportedLanguage();
            Assert.That(dispatcher.TriggerOnSupportedLanguage(language), Is.True);
            Assert.That(seen, Is.SameAs(language));
            Assert.That(Dispatcher.HASH, Is.EqualTo(-1906658668));
        }
    }
}
